#!/usr/bin/env python3
from pathlib import Path
import base64,gzip,hashlib,json,sys
src=Path(sys.argv[1]).resolve(); ev=Path(sys.argv[2]).resolve(); ev.mkdir(parents=True,exist_ok=True)
root=src/'SP/code/rend2'
sha=lambda b: hashlib.sha256(b).hexdigest()
before={p.relative_to(src).as_posix():p.read_bytes() for p in (src/'SP/code').rglob('*') if p.is_file()}
assert sha((root/'tr_elss.inc').read_bytes())=='6bc8c000611dd8c61cca12434581537f5792fb2e6c54bdcab51f3d2bc67d3439'
module=gzip.decompress(base64.b64decode(''''''))
assert sha(module)=='a808886a42da93d287e7213caad9205a5b10b84d7f413c4b9e240585f52ae93a'
(root/'tr_elss.inc').write_bytes(module)

p=root/'tr_local.h'; s=p.read_text()
old='qboolean R_ELSS_SuppressManualDrawSurf(const drawSurf_t *ds,int fixture,unsigned int key);'
new='const unsigned char *R_ELSS_ManualOmitMask(const drawSurf_t *ds,int fixture,unsigned int key,int *triangleCount);'
assert s.count(old)==1
p.write_text(s.replace(old,new))

p=root/'tr_electric_fixture.inc'; s=p.read_text()
old='''    if(fixture<0) {
        if ((backEnd.viewParms.flags & (VPF_SHADOWMAP|VPF_DEPTHSHADOW)) == (VPF_SHADOWMAP|VPF_DEPTHSHADOW) &&
            !(backEnd.viewParms.flags & (VPF_ORTHOGRAPHIC|VPF_FIREVOL_SYNTHETIC_SHADOW)) &&
            R_ELSS_SuppressManualDrawSurf(ds,fixture,backEnd.viewParms.electricFixtureKey)) return;
        goto original;
    }
'''
new='''    if(fixture<0) {
        if ((backEnd.viewParms.flags & (VPF_SHADOWMAP|VPF_DEPTHSHADOW)) == (VPF_SHADOWMAP|VPF_DEPTHSHADOW) &&
            !(backEnd.viewParms.flags & (VPF_ORTHOGRAPHIC|VPF_FIREVOL_SYNTHETIC_SHADOW))) {
            int triangleCount=0;
            const unsigned char *omit=R_ELSS_ManualOmitMask(ds,fixture,backEnd.viewParms.electricFixtureKey,&triangleCount);
            if(omit){RB_SurfaceElectricTrim((srfBspSurface_t *)ds->surface,omit,triangleCount);return;}
        }
        goto original;
    }
'''
assert s.count(old)==1
p.write_text(s.replace(old,new))

after={p.relative_to(src).as_posix():p.read_bytes() for p in (src/'SP/code').rglob('*') if p.is_file()}
changed=sorted(k for k in set(before)|set(after) if before.get(k)!=after.get(k))
assert changed==['SP/code/rend2/tr_electric_fixture.inc','SP/code/rend2/tr_elss.inc','SP/code/rend2/tr_local.h'],changed
assert all(before[k]==after[k] for k in before if '/glsl/' in k)
proof={
 'base':'ELSS V1 on IFLC V1.5 Universal Run 41895006605',
 'version':'ELSS V1.1 Component Pick',
 'changed':changed,
 'profile_read_compat':['DW_ELSS 1','DW_ELSS 2'],
 'profile_write':'DW_ELSS 2',
 'component_pick':'edge-connected triangle component within one BSP surface',
 'architecture_guard':'whole connected component must remain compact and near selected lamp',
 'shadow_slot_preserved':True,
 'direct_preserved':True,
 'local_volumetric_preserved':True,
 'other_casters_preserved':True,
 'iflc_v15u_unchanged':True,
 'glsl_unchanged':True
}
(ev/'ELSS_V11_SOURCE_PROOF.json').write_text(json.dumps(proof,indent=2)+'\n')
(ev/'ELSS_V11_SOURCE_SHA256.json').write_text(json.dumps({k:sha(v) for k,v in after.items()},indent=2)+'\n')
print('ELSS_V11_COMPONENT_PICK_APPLIED',changed)
